const path = require('path');
const fs = require('fs');
const dotenv = require('dotenv');

// Search order for .env files:
// 1. Root .env.local (generated by neon deploy)
// 2. Root .env
// 3. Backend .env
const possibleEnvLocalPaths = [
  path.resolve(__dirname, '../../.env.local'),
  path.resolve(process.cwd(), '.env.local'),
  path.resolve(process.cwd(), '../.env.local'),
  path.resolve(__dirname, '../.env')
];

for (const envPath of possibleEnvLocalPaths) {
  if (fs.existsSync(envPath)) {
    dotenv.config({ path: envPath, override: false });
  }
}

// Always ensure backend/.env is also loaded for local secrets
const backendEnvPath = path.resolve(__dirname, '../.env');
if (fs.existsSync(backendEnvPath)) {
  dotenv.config({ path: backendEnvPath, override: false });
}

module.exports = {
  // Postgres
  DATABASE_URL: process.env.DATABASE_URL,
  DATABASE_URL_UNPOOLED: process.env.DATABASE_URL_UNPOOLED,
  NEON_BRANCH: process.env.NEON_BRANCH || 'production',

  // Auth
  NEON_AUTH_BASE_URL: process.env.NEON_AUTH_BASE_URL,
  NEON_AUTH_JWKS_URL: process.env.NEON_AUTH_JWKS_URL,

  // Object Storage (S3-compatible)
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  AWS_ENDPOINT_URL_S3: process.env.AWS_ENDPOINT_URL_S3,
  AWS_REGION: process.env.AWS_REGION || 'ap-southeast-1',
  BUCKET_NAME: process.env.NEON_BUCKET_NAME || 'assets',

  // Functions
  NEON_FUNCTION_HELLO_BASE_URL: process.env.NEON_FUNCTION_HELLO_BASE_URL,

  // Realtime
  NEON_REALTIME_URL: process.env.NEON_REALTIME_URL,
  NEON_REALTIME_SECRET: process.env.NEON_REALTIME_SECRET
};
